-- Todas las fotos y videos de cada producto de la tienda (orbitaleyewear.com.ar, Shopify; un producto por color).
-- Pedido de Gastón 15/10/2026: la tapa es la foto de la ficha con fondo claro, y en la ficha del catálogo se ven
-- en miniatura todas las del SKU elegido (frente, 45°, lateral, en cara, video).
-- claro = la foto tiene fondo claro (borde con luminancia media >= 215 y < 8% de píxeles oscuros, medido con sharp).
-- url/poster sin el prefijo del CDN de la tienda (ver _tienda_url). vista = lo que dice el alt después de "—".
-- Carga del 15/10 desde /products.json + /products/<handle>.js (público). Para refrescar: regenerar y volver a correr.
create table if not exists public.tienda_media (
  handle text not null, sku text, pos int not null, tipo text not null check (tipo in ('i','v')),
  url text not null, poster text, vista text, claro boolean not null default false,
  cargado_at timestamptz not null default now(), primary key (handle, pos)
);
alter table public.tienda_media enable row level security;
revoke all on public.tienda_media from anon, authenticated;
create index if not exists tienda_media_sku on public.tienda_media (sku);
delete from public.tienda_media;

create or replace function public._tienda_url(p text)
 returns text language sql immutable
as $$ select case when p is null then null when p ~ '^https?://' then p else 'https://cdn.shopify.com/s/files/1/0675/1544/9581/' || p end $$;

-- Producto de la tienda de un SKU. Si dos productos apuntan al mismo SKU (BASEL, MILANO, ZETA 7, SUBLIME, PLUMA),
-- gana el producto original (handle "modelo-N"), no la copia con nombre de color.
create or replace function public._tienda_handle_sku(p_codigo text)
 returns text language sql stable security definer set search_path to 'public'
as $$
  select m.handle from tienda_media m where m.sku = p_codigo
  group by m.handle order by (m.handle ~ '-\d+$') desc, m.handle limit 1
$$;
revoke all on function public._tienda_handle_sku(text) from public, anon, authenticated;

-- Tapa del SKU: la primera foto de la ficha con fondo claro (si no hay, la primera foto; si el SKU no está, tienda_foto)
create or replace function public._tienda_foto_sku(p_codigo text)
 returns text language sql stable security definer set search_path to 'public'
as $$
  select coalesce(
    (select _tienda_url(m.url) from tienda_media m
       where m.handle = _tienda_handle_sku(p_codigo) and m.tipo = 'i'
       order by (not m.claro), m.pos limit 1),
    (select t.imagen from tienda_foto t
       where t.sku = p_codigo and t.imagen !~* 'ficha'
       order by (t.handle ~ '-\d+$') desc, t.handle limit 1))
$$;
revoke all on function public._tienda_foto_sku(text) from public, anon, authenticated;

-- Ficha del catálogo: todas las fotos/videos de la tienda de cada color del modelo (valida la clave como el resto)
create or replace function public.catalogo_media_modelo(p_clave text, p_modelo text)
 returns table(codigo text, pos int, tipo text, url text, poster text, vista text, claro boolean)
 language plpgsql stable security definer set search_path to 'public'
as $function$
begin
  if not catalogo_clave_ok(p_clave) then raise exception 'Clave inválida'; end if;
  return query
  select s.codigo, m.pos, m.tipo, _tienda_url(m.url), _tienda_url(m.poster), m.vista, m.claro
  from stock s
  join tienda_media m on m.handle = _tienda_handle_sku(s.codigo)
  where s.modelo = p_modelo
  order by s.codigo, m.pos;
end; $function$;
revoke all on function public.catalogo_media_modelo(text, text) from public;
grant execute on function public.catalogo_media_modelo(text, text) to anon, authenticated, service_role;

-- Carga masiva: la foto de referencia de cada color también es la de fondo claro
create or replace function public.catalogo_fotos_tienda(p_clave text)
 returns table(modelo text, sku text, tipo text, imagen text)
 language plpgsql stable security definer set search_path to 'public'
as $function$
begin
  if not catalogo_clave_ok(p_clave) then raise exception 'Clave inválida'; end if;
  return query
  select coalesce(s.modelo, t.modelo), t.sku, t.tipo, coalesce(case when t.sku is not null then _tienda_foto_sku(t.sku) end, t.imagen)
  from tienda_foto t left join stock s on s.codigo = t.sku
  where t.imagen !~* 'ficha'
  order by 1, (t.tipo <> 'SOL'), t.handle;
end; $function$;
